insert into public.reviews (id,product_id,user_id,author_label,author_grade,rating,content,situation_tags,photos,helpful,qa_note,created_at) values ('R1001207466-MASTER01','1001207466',NULL,'오컬리','VVIP',5,'재료 손질이 잘 되어 있어서 끓이기만 하면 되니 정말 편했고, 햄과 소시지가 푸짐해서 국물 맛도 진하고 짭짤했어요. 친구들과 술안주로 먹기 딱 좋았습니다.','{"headcount": "2~3인", "purpose": "술안주", "companion": "친구와", "taste": ["짭짤해요", "매콤해요"]}'::jsonb,'{}'::text[],0,'마스터 계정(MASTER01) 리뷰 작성 페이지 진입/열람 테스트용','2026-08-04 10:05'::timestamptz);
insert into public.reviews (id,product_id,user_id,author_label,author_grade,rating,content,situation_tags,photos,helpful,qa_note,created_at) values ('R5047857-MASTER01','5047857',NULL,'오컬리','VVIP',5,'손질이 깔끔하게 되어 있어서 굽기만 해도 레스토랑에서 먹는 듯한 맛이 났어요. 지방이 적당히 있어 담백하면서도 부드러워서 부모님 모시고 먹기 좋았습니다.','{"headcount": "2~3인", "purpose": "일상", "companion": "부모님과", "taste": ["담백해요"]}'::jsonb,'{}'::text[],0,'마스터 계정(MASTER01) 리뷰 작성 페이지 진입/열람 테스트용','2026-08-04 10:10'::timestamptz);

-- 9) review_count 동기화

update public.products p
set review_count = coalesce((select count(*) from public.reviews r where r.product_id = p.id), 0);


